draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure with heart
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // heart size changes with Math.sin(t)
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fillStyle = 'red';
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.stroke();

  // choice arrow
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 70 + 10 * Math.cos(t), H/2);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 + 10 * Math.cos(t), H/2);
  ctx.lineTo(W/2 + 70 + 10 * Math.cos(t) - 10, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 + 10 * Math.cos(t), H/2);
  ctx.lineTo(W/2 + 70 + 10 * Math.cos(t) - 10, H/2 + 10);
  ctx.stroke();

  ctx.restore();
}
